Lemma geo_1RB1RB_0LB1RC_1LD0RC_0LD1LA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1RB_0LB1RC_1LD0RC_0LD1LA) = lift (Cc (Pos.succ p)).
