Lemma fire_1RB1RB_0LC1RB_1RA1LD_1LC0RB : forall t, ~ In t pins_1RB1RB_0LC1RB_1RA1LD_1LC0RB ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
