Lemma lapi_1RB1RB_0RC1RB_1LD0RC_0LD1LA : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_1RB1RB_0RC1RB_1LD0RC_0LD1LA p q0 E) as (HA & HB).
    exists (0 * 0 + 6). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_1RB1RB_0RC1RB_1LD0RC_0LD1LA Z0_1RB1RB_0RC1RB_1LD0RC_0LD1LA Z1_1RB1RB_0RC1RB_1LD0RC_0LD1LA 0 6
               run_z_1RB1RB_0RC1RB_1LD0RC_0LD1LA (Kp q0 ++ [S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_1RB1RB_0RC1RB_1LD0RC_0LD1LA p j' q0 E) as (HA & HB).
    exists (2 * j' + 8). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_1RB1RB_0RC1RB_1LD0RC_0LD1LA P0_1RB1RB_0RC1RB_1LD0RC_0LD1LA P1_1RB1RB_0RC1RB_1LD0RC_0LD1LA 2 8
               run_p_1RB1RB_0RC1RB_1LD0RC_0LD1LA (Kp q0 ++ [S0]) [] j'
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
Qed.

Lemma gso_1RB1RB_0RC1RB_1LD0RC_0LD1LA : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB1RB_0RC1RB_1LD0RC_0LD1LA.
Proof.
  intros p j E. destruct (KpCounter.cview_none_K p j E) as (H1 & _).
  unfold Cc_1RB1RB_0RC1RB_1LD0RC_0LD1LA, cden, B0_1RB1RB_0RC1RB_1LD0RC_0LD1LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB1RB_0RC1RB_1LD0RC_0LD1LA : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB1RB_0RC1RB_1LD0RC_0LD1LA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1RB_0RC1RB_1LD0RC_0LD1LA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (KpCounter.cview_none_K p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB1RB_0RC1RB_1LD0RC_0LD1LA
             = (StB, (rep [S0] (S j) ++ [S1], S0, [S1;S1]))).
  { unfold cden, B1_1RB1RB_0RC1RB_1LD0RC_0LD1LA, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StB, ((rep [S0] (S j) ++ [S1]) ++ [S0], S0, [S1;S1]))).
  { unfold Cc_1RB1RB_0RC1RB_1LD0RC_0LD1LA. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_1RB1RB_0RC1RB_1LD0RC_0LD1LA. reflexivity.
Qed.

(** ** The lap *)

Lemma lap_1RB1RB_0RC1RB_1LD0RC_0LD1LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1RB_0RC1RB_1LD0RC_0LD1LA p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1RB_0RC1RB_1LD0RC_0LD1LA B0_1RB1RB_0RC1RB_1LD0RC_0LD1LA B1_1RB1RB_0RC1RB_1LD0RC_0LD1LA 2 8 p j' [] []).
    + exact run_ovf_1RB1RB_0RC1RB_1LD0RC_0LD1LA.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1RB_0RC1RB_1LD0RC_0LD1LA p j' E).
    + exact (geo_1RB1RB_0RC1RB_1LD0RC_0LD1LA p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma bootq_1RB1RB_0RC1RB_1LD0RC_0LD1LA : stepn tmm_1RB1RB_0RC1RB_1LD0RC_0LD1LA 7 InitES = Some (lift (Cc 1)).
Proof.
  assert (H : match csteps tmm_1RB1RB_0RC1RB_1LD0RC_0LD1LA 7 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tmm_1RB1RB_0RC1RB_1LD0RC_0LD1LA 7 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** the quasihalt witness: a pinned instruction fired in the prefix *)
Lemma wit_1RB1RB_0RC1RB_1LD0RC_0LD1LA : existsb (fun tg => cfires tmm_1RB1RB_0RC1RB_1LD0RC_0LD1LA c0 7 tg) pins_1RB1RB_0RC1RB_1LD0RC_0LD1LA = true.
Proof. vm_compute. reflexivity. Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1RB_0RC1RB_1LD0RC_0LD1LA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1RB_0RC1RB_1LD0RC_0LD1LA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB1RB_0RC1RB_1LD0RC_0LD1LA p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1RB_0RC1RB_1LD0RC_0LD1LA p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1RB_0RC1RB_1LD0RC_0LD1LA : forall t, ~ In t pins_1RB1RB_0RC1RB_1LD0RC_0LD1LA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB1RB_0RC1RB_1LD0RC_0LD1LA.
  destruct t as [q b]; destruct q, b.
  - (* A0: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB1RB_0RC1RB_1LD0RC_0LD1LA
      with (l := [SWin 1; SCycL 1 0; SWin 2; SCycR 1; SWin 3]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB1RB_0RC1RB_1LD0RC_0LD1LA
      with (l := []).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB1RB_0RC1RB_1LD0RC_0LD1LA
      with (l := [SWin 1; SCycL 1 0; SWin 2; SCycR 1; SWin 4]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB1RB_0RC1RB_1LD0RC_0LD1LA
      with (l := [SWin 1; SCycL 1 0; SWin 1]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB1RB_0RC1RB_1LD0RC_0LD1LA
      with (l := [SWin 1]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB1RB_0RC1RB_1LD0RC_0LD1LA
      with (l := [SWin 1; SCycL 1 0; SWin 2]).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB1RB_0RC1RB_1LD0RC_0LD1LA
      with (l := [SWin 1; SCycL 1 0; SWin 2; SCycR 1; SWin 2]).
    vm_compute; reflexivity.
Qed.

