Proof.
  apply (lap_qh_stage tmm_1RB1RB_0RC1RB_1LD0RC_0LD1LA pins_1RB1RB_0RC1RB_1LD0RC_0LD1LA Cc 1 7 32779478).
  - exact bootq_1RB1RB_0RC1RB_1LD0RC_0LD1LA.
  - intros p _. apply lap_1RB1RB_0RC1RB_1LD0RC_0LD1LA.
  - intros t Ht p _. apply fire_1RB1RB_0RC1RB_1LD0RC_0LD1LA. exact Ht.
  - exact wit_1RB1RB_0RC1RB_1LD0RC_0LD1LA.
  - apply qcleb_QC_27. reflexivity.
Qed.

Theorem qhtr_1RB1RB_0RC1RB_1LD0RC_0LD1LA : NonHalt tm_1RB1RB_0RC1RB_1LD0RC_0LD1LA /\ QHBoundTr 32779478 tm_1RB1RB_0RC1RB_1LD0RC_0LD1LA /\ QuasiHaltsTr tm_1RB1RB_0RC1RB_1LD0RC_0LD1LA.
Proof. apply (qh_triple_unmirror 32779478 tm_1RB1RB_0RC1RB_1LD0RC_0LD1LA). rewrite mirror_ok_1RB1RB_0RC1RB_1LD0RC_0LD1LA. exact qhtrm_1RB1RB_0RC1RB_1LD0RC_0LD1LA. Qed.

