    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1RB_1LA0RC_1LD0RC_0LD1RB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1RB_1LA0RC_1LD0RC_0LD1RB = Some t ->
