  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB1RB_1LA0RC_1LD0RC_0LD1RB
      with (l := []).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB1RB_1LA0RC_1LD0RC_0LD1RB
      with (l := [SWin 2]).
    vm_compute; reflexivity.
  - (* C0 *)
