    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB1RB_1LA0RC_1LD0RC_0LD1RB
      with (l := [SWin 3; SCycL 1 0; SWin 2]).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB1RB_1LA0RC_1LD0RC_0LD1RB
      with (l := [SWin 3; SCycL 1 0; SWin 2; SCycR 1; SWin 2]).
    vm_compute; reflexivity.
Qed.

