(** ** The certificate *)

Definition A0_1RB1RB_1LA1LC_1RD0LC_0RD1LA : sconf := mkC StD (mkS [] [S1] 1 0 [S0]) S0 (mkS [S1] [] 0 0 []).
Definition A1_1RB1RB_1LA1LC_1RD0LC_0RD1LA : sconf := mkC StD (mkS [] [S0] 1 0 [S1]) S0 (mkS [S1] [] 0 0 []).
Definition chi_1RB1RB_1LA1LC_1RD0LC_0RD1LA : list lstep := [SWin 4; SCycL 1 0; SWin 2; SCycR 1].

Lemma run_int_1RB1RB_1LA1LC_1RD0LC_0RD1LA : srun tm false true chi_1RB1RB_1LA1LC_1RD0LC_0RD1LA A0_1RB1RB_1LA1LC_1RD0LC_0RD1LA = Some (A1_1RB1RB_1LA1LC_1RD0LC_0RD1LA, 2, 6).
