Lemma run_ovf_1RB1RB_1LA1LC_1RD0LC_0RD1LA : srun tm true true cho_1RB1RB_1LA1LC_1RD0LC_0RD1LA B0_1RB1RB_1LA1LC_1RD0LC_0RD1LA = Some (B1_1RB1RB_1LA1LC_1RD0LC_0RD1LA, 2, 8).
