      with (l := []).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB1RB_1LB1LC_1RD0LC_0RD1LA
      with (l := [SWin 1]).
    vm_compute; reflexivity.
Qed.

