    apply (lap_of_run tm Cc true true cho_1RB1RB_1LC0RB_0LC0RD_1LA1RD B0_1RB1RB_1LC0RB_0LC0RD_1LA1RD B1_1RB1RB_1LC0RB_0LC0RD_1LA1RD 2 8 p j' [] []).
    + exact run_ovf_1RB1RB_1LC0RB_0LC0RD_1LA1RD.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1RB_1LC0RB_0LC0RD_1LA1RD p j' E).
    + exact (geo_1RB1RB_1LC0RB_0LC0RD_1LA1RD p j' E).
