    apply (fire_via_ovf_lift tm Cc Hi (StC, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RB_1LC0RB_0LC0RD_1LA1RD [SWinR 3; SCycL 1 0; SWin 2; SCycR 1; SWin 2] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
